-- [10] CASE-Expression Sort Plus String-Concat Sort Key
-- Sorts by a computed CASE, then by a concatenated string nobody indexed because you can't.
SELECT o.order_id, o.status, c.full_name, o.order_date
FROM orders o JOIN customers c ON c.customer_id = o.customer_id
ORDER BY
  CASE o.status
