-- [12] SELECT-List Full Of Aggregate Subqueries
-- Three independent aggregate subqueries per customer row instead of one GROUP BY.
SELECT c.customer_id, c.full_name,
  (SELECT COUNT(*) FROM orders o WHERE o.customer_id = c.customer_id) AS order_count,
  (SELECT COALESCE(SUM(oi.quantity*oi.unit_price),0)
     FROM orders o JOIN order_items oi ON oi.order_id = o.order_id
     WHERE o.customer_id = c.customer_id) AS lifetime_value,
  (SELECT MAX(o.order_date) FROM orders o WHERE o.customer_id = c.customer_id) AS last_order
FROM customers c
ORDER BY lifetime_value DESC;
